import { PERFORMANCE_TOOL_PATH } from '../../../constants';

export const getPerformanceToolBreadcrumbHref = (
  kpi: string | undefined,
  marketShareVersion: string | null,
) => {
  const isMarketShareV2 = kpi === 'market_share' && marketShareVersion === 'v2';

  return isMarketShareV2
    ? '/value-creation/market-share-v2'
    : PERFORMANCE_TOOL_PATH;
};
